    27  /**
    28   * A length-safe version of strchr(). This function returns a pointer
    29   * to the first occurrence of @p c  in @p s, or @c NULL if not found.
    30   *
    31   * @param s   The string to search for @p c.
    32   * @param len The length of @p s.
    33   * @param c   The character to search.
    34   *
    35   * @return A pointer to the first occurence of @p c, or @c NULL
    36   * if not found.
    37   */
    38  COAP_STATIC_INLINE const uint8_t *
    39  strnchr(const uint8_t *s, size_t len, unsigned char c) {
    40    while (len && *s++ != c)
    41      --len;
    42
    43    return len ? s : NULL;
    44  }
    45
    46  #define ISEQUAL_CI(a,b) \
    47    ((a) == (b) || (islower(b) && ((a) == ((b) - 0x20))))
    48
    49  typedef enum coap_uri_check_t {
    50    COAP_URI_CHECK_URI,
    51    COAP_URI_CHECK_PROXY
    52  } coap_uri_check_t;
    53
    54  static int
    55  coap_split_uri_sub(const uint8_t *str_var,
    56                     size_t len,
    57                     coap_uri_t *uri,
    58                     coap_uri_check_t check_proxy) {
    59    const uint8_t *p, *q;
    60    int res = 0;
    61    int is_http_proxy_scheme = 0;
    62    size_t keep_len = len;
    63
    64    if (!str_var || !uri)
    65      return -1;
    66
    67    memset(uri, 0, sizeof(coap_uri_t));
    68    uri->port = COAP_DEFAULT_PORT;
    69
    70    /* search for scheme */
    71    p = str_var;
    72    if (*p == '/') {
    73      if (check_proxy == COAP_URI_CHECK_PROXY)
    74        return -1;
    75      q = p;
    76      goto path;
    77    }
    78
    79    q = (const uint8_t *)COAP_DEFAULT_SCHEME;
    80    while (len && *q && ISEQUAL_CI(*p, *q)) {
    81      ++p; ++q; --len;
    82    }
    83    if (*q && check_proxy == COAP_URI_CHECK_PROXY) {
    84      /* Scheme could be something other than coap */
    85      len = keep_len;
    86      p = str_var;
    87      q = (const uint8_t *)"http";
    88      while (len && *q && ISEQUAL_CI(*p, *q)) {
    89        ++p; ++q; --len;
    90      }
    91      if (*q == 0) {
    92        if (len && ISEQUAL_CI(*p, 's')) {
    93          /* https:// */
    94          ++p; --len;
    95          uri->scheme = COAP_URI_SCHEME_HTTPS;
    96          uri->port = 443;
    97        }
    98        else {
    99          /* http:// */
   100          uri->scheme = COAP_URI_SCHEME_HTTP;
   101          uri->port = 80;
   102        }
   103      }
   104      else {
   105        /* Unknown scheme */
   106        res = -1;
   107        goto error;
   108      }
   109      is_http_proxy_scheme = 1;
   110    }
   111
   112    /* If q does not point to the string end marker '\0', the schema
   113     * identifier is wrong. */
   114    if (*q) {
   115      res = -1;
   116      goto error;
   117    }
   118
   119    if (is_http_proxy_scheme == 0) {
   120      /* There might be an additional 's', indicating the secure version: */
   121      if (len && (*p == 's')) {
   122        ++p; --len;
   123        uri->scheme = COAP_URI_SCHEME_COAPS;
   124        uri->port = COAPS_DEFAULT_PORT;
   125      } else {
   126        uri->scheme = COAP_URI_SCHEME_COAP;
   127      }
   128
   129      /* There might be an addition "+tcp", indicating reliable transport: */
   130      if (len>=4 && p[0] == '+' && p[1] == 't' && p[2] == 'c' && p[3] == 'p' ) {
   131        p += 4;
   132        len -= 4;
   133        if (uri->scheme == COAP_URI_SCHEME_COAPS)
   134          uri->scheme = COAP_URI_SCHEME_COAPS_TCP;
   135        else
   136          uri->scheme = COAP_URI_SCHEME_COAP_TCP;
   137      }
   138    }
   139    q = (const uint8_t *)"://";
   140    while (len && *q && *p == *q) {
   141      ++p; ++q; --len;
   142    }
   143
   144    if (*q) {
   145      res = -2;
   146      goto error;
   147    }
   148
   149    /* p points to beginning of Uri-Host */
   150    q = p;
   151    if (len && *p == '[') {        /* IPv6 address reference */
   152      ++p;
   153
   154      while (len && *q != ']') {
   155        ++q; --len;
   156      }
   157
   158      if (!len || *q != ']' || p == q) {
   159        res = -3;
   160        goto error;
   161      }
   162
   163      COAP_SET_STR(&uri->host, q - p, p);
   164      ++q; --len;
   165    } else {                        /* IPv4 address or FQDN */
   166      while (len && *q != ':' && *q != '/' && *q != '?') {
   167        ++q;
   168        --len;
   169      }
   170
   171      if (p == q) {
   172        res = -3;
   173        goto error;
   174      }
   175
   176      COAP_SET_STR(&uri->host, q - p, p);
   177    }
   178
   179    /* check for Uri-Port */
   180    if (len && *q == ':') {
   181      p = ++q;
   182      --len;
   183
   184      while (len && isdigit(*q)) {
   185        ++q;
   186        --len;
   187      }
   188
   189      if (p < q) {                /* explicit port number given */
   190        int uri_port = 0;
   191
   192        while ((p < q) && (uri_port <= UINT16_MAX))
   193                uri_port = uri_port * 10 + (*p++ - '0');
   194
   195        /* check if port number is in allowed range */
   196        if (uri_port > UINT16_MAX) {
   197                res = -4;
   198                goto error;
   199        }
   200
   201        uri->port = (uint16_t)uri_port;
   202      }
   203    }
   204
   205   path:                 /* at this point, p must point to an absolute path */
   206
   207    if (!len)
   208      goto end;
   209
   210    if (*q == '/') {
   211      p = ++q;
   212      --len;
   213
   214      while (len && *q != '?') {
   215        ++q;
   216        --len;
   217      }
   218
   219      if (p < q) {
   220        COAP_SET_STR(&uri->path, q - p, p);
   221        p = q;
   222      }
   223    }
   224
   225    /* Uri_Query */
   226    if (len && *p == '?') {
   227      ++p;
   228      --len;
   229      COAP_SET_STR(&uri->query, len, p);
   230      len = 0;
   231    }
   232
   233    end:
   234    return len ? -1 : 0;
   235
   236    error:
   237    return res;
   238  }
